	private boolean isInRequiredFriendsChat()
	{
		FriendsChatManager manager =
				client.getFriendsChatManager();

		if (manager == null
				|| manager.getName() == null)
		{
			return false;
		}

		return normalizeName(
				REQUIRED_FRIENDS_CHAT
		).equals(
				normalizeName(
						manager.getName()
				)
		);
	}

	private boolean isStaffRankAuthorized()
	{
		boolean inRequiredChat =
				isInRequiredFriendsChat();

		if (!inRequiredChat)
		{
			unauthorizedStaffRankObservedAt = null;

			return cachedStaffRankCheckedAt != null
					&& cachedStaffRankAuthorized;
		}

		Instant now = Instant.now();

		if (cachedStaffRankAuthorized
				&& cachedStaffRankCheckedAt != null
				&& Duration.between(
				cachedStaffRankCheckedAt,
				now
		).compareTo(
				STAFF_RANK_CACHE_DURATION
		) < 0)
		{
			return true;
		}

		FriendsChatManager manager =
				client.getFriendsChatManager();

		FriendsChatRank rank =
				manager == null
						? null
						: manager.getMyRank();

		if (rank == null)
		{
			return cachedStaffRankCheckedAt != null
					&& cachedStaffRankAuthorized;
		}

		boolean authorized;

		switch (rank)
		{
			case LIEUTENANT:
			case CAPTAIN:
			case GENERAL:
			case OWNER:
				authorized = true;
				break;
			default:
				authorized = false;
		}

		if (authorized)
		{
			cachedStaffRankAuthorized = true;
			cachedStaffRankCheckedAt = now;
			unauthorizedStaffRankObservedAt = null;

			return true;
		}

		if (cachedStaffRankAuthorized)
		{
			if (unauthorizedStaffRankObservedAt == null)
			{
				unauthorizedStaffRankObservedAt = now;
				return true;
			}

			if (Duration.between(
					unauthorizedStaffRankObservedAt,
					now
			).compareTo(
					STAFF_RANK_REVOCATION_GRACE
			) < 0)
			{
				return true;
			}
		}

		cachedStaffRankAuthorized = false;
		cachedStaffRankCheckedAt = now;
		unauthorizedStaffRankObservedAt = null;

		return false;
	}

	private void applySyncedPartyCredential(
			SyncedPartyCredential credential)
			throws GeneralSecurityException
	{
		if (credential == null)
		{
			throw new GeneralSecurityException(
					"Missing Party credential"
			);
		}

		if (!credential.available)
		{
			configManager.setConfiguration(
					CONFIG_GROUP,
					PARTY_SYNC_VERSION_KEY,
					Integer.toString(
							credential.version
					)
			);

			configManager.unsetConfiguration(
					CONFIG_GROUP,
					PARTY_SYNC_NONCE_KEY
			);

			configManager.unsetConfiguration(
					CONFIG_GROUP,
					PARTY_SYNC_CIPHERTEXT_KEY
			);

			configManager.unsetConfiguration(
					CONFIG_GROUP,
					PARTY_SYNC_MAC_KEY
			);

			return;
		}

		String decrypted =
				decryptPartyCredential(
						credential
				);

		if (decrypted.isEmpty())
		{
			throw new GeneralSecurityException(
					"Party credential decrypted to an empty value"
			);
		}

		configManager.setConfiguration(
				CONFIG_GROUP,
				PARTY_SYNC_VERSION_KEY,
				Integer.toString(
						credential.version
				)
		);

		configManager.setConfiguration(
				CONFIG_GROUP,
				PARTY_SYNC_NONCE_KEY,
				credential.nonce
		);

		configManager.setConfiguration(
				CONFIG_GROUP,
				PARTY_SYNC_CIPHERTEXT_KEY,
				credential.ciphertext
		);

		configManager.setConfiguration(
				CONFIG_GROUP,
				PARTY_SYNC_MAC_KEY,
				credential.mac
		);
	}

	private String decryptPartyPassphrase()
	{
		String versionText =
				configManager.getConfiguration(
						CONFIG_GROUP,
						PARTY_SYNC_VERSION_KEY
				);

		String nonce =
				configManager.getConfiguration(
						CONFIG_GROUP,
						PARTY_SYNC_NONCE_KEY
				);

		String ciphertext =
				configManager.getConfiguration(
						CONFIG_GROUP,
						PARTY_SYNC_CIPHERTEXT_KEY
				);

		String mac =
				configManager.getConfiguration(
						CONFIG_GROUP,
						PARTY_SYNC_MAC_KEY
				);

		if (versionText == null
				|| nonce == null
				|| ciphertext == null
				|| mac == null)
		{
			return null;
		}

		try
		{
			int version =
					Integer.parseInt(
							versionText
					);

			return decryptPartyCredential(
					new SyncedPartyCredential(
							version,
							true,
							nonce,
							ciphertext,
							mac
					)
			);
		}
		catch (GeneralSecurityException
		       | IllegalArgumentException exception)
		{
			log.debug(
					"Unable to decrypt synced Party passphrase",
					exception
			);

			return null;
		}
	}

	private String decryptPartyCredential(
			SyncedPartyCredential credential)
			throws GeneralSecurityException
	{
		byte[] rootKey = null;
		byte[] encryptionKey = null;
		byte[] authenticationKey = null;
		byte[] nonce = null;
		byte[] ciphertext = null;
		byte[] plaintext = null;

		try
		{
			rootKey = Base64.getDecoder().decode(
					PARTY_SYNC_ROOT_KEY_BASE64
			);

			nonce = Base64.getDecoder().decode(
					credential.nonce
			);

			ciphertext = Base64.getDecoder().decode(
					credential.ciphertext
			);

			byte[] suppliedMac =
					Base64.getDecoder().decode(
							credential.mac
					);

			encryptionKey = hmacSha256(
					rootKey,
					"party-sync-encryption"
							.getBytes(
									StandardCharsets.UTF_8
							)
			);

			authenticationKey = hmacSha256(
					rootKey,
					"party-sync-authentication"
							.getBytes(
									StandardCharsets.UTF_8
							)
			);

			String macMessage =
					credential.version
							+ "|"
							+ credential.nonce
							+ "|"
							+ credential.ciphertext;

			byte[] expectedMac =
					hmacSha256(
							authenticationKey,
							macMessage.getBytes(
									StandardCharsets.UTF_8
							)
					);

			if (!MessageDigest.isEqual(
					expectedMac,
					suppliedMac
			))
			{
				throw new GeneralSecurityException(
						"Party credential authentication failed"
				);
			}

			plaintext = cryptPartyBytes(
					ciphertext,
					encryptionKey,
					nonce
			);

			return new String(
					plaintext,
					StandardCharsets.UTF_8
			);
		}
		catch (IllegalArgumentException exception)
		{
			throw new GeneralSecurityException(
					"Invalid Party credential encoding",
					exception
			);
		}
		finally
		{
			wipe(rootKey);
			wipe(encryptionKey);
			wipe(authenticationKey);
			wipe(nonce);
			wipe(ciphertext);
			wipe(plaintext);
		}
	}

	private byte[] cryptPartyBytes(
			byte[] input,
			byte[] encryptionKey,
			byte[] nonce)
			throws GeneralSecurityException
	{
		byte[] output =
				new byte[input.length];

		int offset = 0;
		int counter = 1;

		while (offset < input.length)
		{
			byte[] blockInput =
					new byte[
							nonce.length + 4
							];

			System.arraycopy(
					nonce,
					0,
					blockInput,
					0,
					nonce.length
			);

			int counterOffset =
					nonce.length;

			blockInput[counterOffset] =
					(byte) (
							counter >>> 24
					);

			blockInput[counterOffset + 1] =
					(byte) (
							counter >>> 16
					);

			blockInput[counterOffset + 2] =
					(byte) (
							counter >>> 8
					);

			blockInput[counterOffset + 3] =
					(byte) counter;

			byte[] keystream =
					hmacSha256(
							encryptionKey,
							blockInput
					);

			try
			{
				for (int index = 0;
				     index < keystream.length
							 && offset < input.length;
				     index++, offset++)
				{
					output[offset] =
							(byte) (
									input[offset]
											^ keystream[index]
							);
				}
			}
			finally
			{
				wipe(keystream);
				wipe(blockInput);
			}

			counter++;
		}

		return output;
	}

	private byte[] hmacSha256(
			byte[] key,
			byte[] data)
			throws GeneralSecurityException
	{
		Mac mac = Mac.getInstance(
				"HmacSHA256"
		);

		mac.init(
				new SecretKeySpec(
						key,
						"HmacSHA256"
				)
		);

		return mac.doFinal(data);
	}

	private void wipe(byte[] value)
	{
		if (value != null)
		{
			Arrays.fill(
					value,
					(byte) 0
			);
		}
	}

