	private Set<String> parseConfiguredNames(
			String configuredNames)
	{
		Set<String> names = new HashSet<>();

		if (configuredNames == null
				|| configuredNames.trim().isEmpty())
		{
			return names;
		}

		Arrays.stream(
						configuredNames.split(
								"[,\\r\\n]+"
						)
				)
				.map(String::trim)
				.map(this::normalizeName)
				.filter(name -> !name.isEmpty())
				.forEach(names::add);

		return names;
	}

	private void applyLevelsToMemberList()
	{
		if (!isStaffFeaturesActive())
		{
			return;
		}

		Widget chatList =
				client.getWidget(
						InterfaceID
								.ChatchannelCurrent
								.LIST
				);

		if (chatList == null
				|| chatList.getChildren() == null)
		{
			return;
		}

		Set<String> ignoredNames =
				getIgnoredNames();

		Set<String> bannedNames =
				getBannedNames();

		Widget[] children =
				chatList.getChildren();

		List<FriendsChatRow> rows =
				new ArrayList<>();

		for (int i = 0;
		     i < children.length;
		     i += 3)
		{
			Widget nameWidget = children[i];

			if (nameWidget == null)
			{
				continue;
			}

			String originalText =
					removePluginFormatting(
							nameWidget.getText()
					);

			String playerName =
					Text.toJagexName(
							Text.removeTags(
									originalText
							)
					);

			String normalizedName =
					normalizeName(playerName);

			int priority =
					getFriendsChatSortPriority(
							normalizedName,
							ignoredNames,
							bannedNames
					);

			rows.add(
					new FriendsChatRow(
							getRowWidgets(
									children,
									i
							),
							nameWidget.getOriginalY(),
							priority
					)
			);

			if (bannedNames.contains(
					normalizedName
			))
			{
				cancelLookup(normalizedName);

				thievingLevels.remove(
						normalizedName
				);

				lowLevelMembers.remove(
						normalizedName
				);

				nameWidget.setText(
						RED_TEXT_OPEN
								+ originalText
								+ BANNED_MEMBER_TEXT
								+ TEXT_CLOSE
				);

				continue;
			}

			if (unrankedF2pMembers.contains(
					normalizedName
			))
			{
				String f2pColorOpen =
						ignoredNames.contains(
								normalizedName
						)
								? "<col=00ff00>"
								: RED_TEXT_OPEN;

				nameWidget.setText(
						f2pColorOpen
								+ originalText
								+ F2P_MEMBER_TEXT
								+ TEXT_CLOSE
				);

				continue;
			}

			Integer thievingLevel =
					thievingLevels.get(
							normalizedName
					);

			if (thievingLevel == null)
			{
				nameWidget.setText(
						originalText
				);

				continue;
			}

			boolean showGreen =
					thievingLevel
							>= REQUIRED_THIEVING_LEVEL
							|| ignoredNames.contains(
							normalizedName
					);

			String levelMarker =
					showGreen
							? GREEN_LEVEL_MARKER
							: RED_LEVEL_MARKER;

			nameWidget.setText(
					originalText
							+ levelMarker
							+ thievingLevel
							+ LEVEL_SUFFIX
			);
		}

		sortFriendsChatRows(rows);
	}

	private int getFriendsChatSortPriority(
			String normalizedName,
			Set<String> ignoredNames,
			Set<String> bannedNames)
	{
		if (bannedNames.contains(normalizedName))
		{
			return 0;
		}

		if (unrankedF2pMembers.contains(
				normalizedName
		)
				&& !ignoredNames.contains(
				normalizedName
		))
		{
			return 1;
		}

		Integer thievingLevel =
				thievingLevels.get(normalizedName);

		if (thievingLevel != null
				&& thievingLevel < REQUIRED_THIEVING_LEVEL
				&& !ignoredNames.contains(normalizedName))
		{
			return 2;
		}

		return 3;
	}

	private List<Widget> getRowWidgets(
			Widget[] children,
			int startIndex)
	{
		List<Widget> rowWidgets =
				new ArrayList<>(3);

		for (int i = startIndex;
		     i < children.length
					 && i < startIndex + 3;
		     i++)
		{
			Widget widget = children[i];

			if (widget != null)
			{
				rowWidgets.add(widget);
			}
		}

		return rowWidgets;
	}

	private void sortFriendsChatRows(
			List<FriendsChatRow> rows)
	{
		if (rows.size() < 2)
		{
			return;
		}

		List<Integer> rowPositions =
				new ArrayList<>(rows.size());

		for (FriendsChatRow row : rows)
		{
			rowPositions.add(row.baseY);
		}

		rowPositions.sort(Integer::compareTo);

		rows.sort(
				Comparator.comparingInt(
						row -> row.priority
				)
		);

		for (int i = 0; i < rows.size(); i++)
		{
			rows.get(i).moveTo(
					rowPositions.get(i)
			);
		}
	}

