	private String removePluginFormatting(
			String text)
	{
		if (text == null)
		{
			return "";
		}

		String withoutLevel =
				removeLevelFromText(text);

		String plainText =
				Text.removeTags(withoutLevel);

		if (plainText.endsWith(
				BANNED_MEMBER_TEXT
		))
		{
			plainText = plainText.substring(
					0,
					plainText.length()
							- BANNED_MEMBER_TEXT.length()
			);
		}
		else if (plainText.endsWith(
				F2P_MEMBER_TEXT
		))
		{
			plainText = plainText.substring(
					0,
					plainText.length()
							- F2P_MEMBER_TEXT.length()
			);
		}

		return plainText;
	}

	private String removeLevelFromText(
			String text)
	{
		if (text == null)
		{
			return "";
		}

		int greenIndex =
				text.indexOf(
						GREEN_LEVEL_MARKER
				);

		int redIndex =
				text.indexOf(
						RED_LEVEL_MARKER
				);

		int markerIndex;

		if (greenIndex == -1)
		{
			markerIndex = redIndex;
		}
		else if (redIndex == -1)
		{
			markerIndex = greenIndex;
		}
		else
		{
			markerIndex = Math.min(
					greenIndex,
					redIndex
			);
		}

		return markerIndex == -1
				? text
				: text.substring(
				0,
				markerIndex
		);
	}

	private String normalizeName(
			String playerName)
	{
		if (playerName == null)
		{
			return "";
		}

		return Text.toJagexName(
				Text.removeTags(playerName)
		).toLowerCase(Locale.ROOT);
	}


